const express = require('express');
const crypto = require('crypto');
const app = express();

// Feature flag configuration
const featureFlags = {
  ENABLE_SSO_REDIRECT: true,
  ENABLE_PARTNER_REDIRECTS: true,
  STRICT_REDIRECT_VALIDATION: true,
  ALLOW_SUBDOMAIN_REDIRECTS: true
};

// Trusted domains registry
const TRUSTED_DOMAINS = [
  'app.example.com',
  'auth.example.com',
  'portal.example.com',
  'cdn.example.com'
];

// Partner domains added via config
const PARTNER_DOMAINS = [
  'partner1.trusted-corp.com',
  'partner2.trusted-corp.com'
];

function getAllowedDomains() {
  const domains = [...TRUSTED_DOMAINS];
  if (featureFlags.ENABLE_PARTNER_REDIRECTS) {
    domains.push(...PARTNER_DOMAINS);
  }
  return domains;
}

function normalizeUrl(urlString) {
  try {
    // Handle protocol-relative URLs
    if (urlString.startsWith('//')) {
      urlString = 'https:' + urlString;
    }
    // Handle relative URLs
    if (!urlString.includes('://') && !urlString.startsWith('/')) {
      urlString = 'https://' + urlString;
    }
    return urlString;
  } catch (e) {
    return null;
  }
}

function extractHostname(urlString) {
  try {
    const normalized = normalizeUrl(urlString);
    if (!normalized) return null;
    const parsed = new URL(normalized);
    return parsed.hostname;
  } catch (e) {
    return null;
  }
}

function isDomainAllowed(hostname, allowedDomains) {
  if (!hostname) return false;

  for (const domain of allowedDomains) {
    if (hostname === domain) return true;

    // Allow subdomains if feature flag is enabled
    if (featureFlags.ALLOW_SUBDOMAIN_REDIRECTS) {
      if (hostname.endsWith('.' + domain)) return true;
    }
  }
  return false;
}

function validateRedirectTarget(target) {
  // Allow relative paths always
  if (target.startsWith('/') && !target.startsWith('//')) {
    return { valid: true, url: target };
  }

  const hostname = extractHostname(target);
  if (!hostname) {
    return { valid: false, reason: 'invalid_url' };
  }

  const allowedDomains = getAllowedDomains();

  if (featureFlags.STRICT_REDIRECT_VALIDATION) {
    if (!isDomainAllowed(hostname, allowedDomains)) {
      return { valid: false, reason: 'domain_not_allowed' };
    }
  }

  return { valid: true, url: target };
}

function buildRedirectUrl(target, sessionToken) {
  const normalized = normalizeUrl(target);
  if (!normalized) return target;

  try {
    const url = new URL(normalized);
    if (sessionToken) {
      url.searchParams.set('session', sessionToken);
    }
    return url.toString();
  } catch (e) {
    return target;
  }
}

// SSO callback endpoint
app.get('/auth/callback', (req, res) => {
  const { redirect_to, state } = req.query;

  if (!redirect_to) {
    return res.redirect('/dashboard');
  }

  // Decode the redirect target
  const target = decodeURIComponent(redirect_to);

  const validation = validateRedirectTarget(target);

  if (!validation.valid) {
    console.warn(`Blocked redirect to: ${target} (${validation.reason})`);
    return res.status(400).json({ error: 'Invalid redirect target' });
  }

  // Generate session token
  const sessionToken = crypto.randomBytes(16).toString('hex');

  const finalUrl = featureFlags.ENABLE_SSO_REDIRECT 
    ? buildRedirectUrl(validation.url, sessionToken)
    : '/dashboard';

  res.redirect(302, finalUrl);
});

// Partner redirect endpoint
app.get('/api/v1/redirect', (req, res) => {
  const { url, partner_id } = req.query;

  if (!url || !partner_id) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const target = Buffer.from(url, 'base64').toString('utf8');
  const validation = validateRedirectTarget(target);

  if (!validation.valid) {
    return res.status(403).json({ error: 'Redirect not allowed' });
  }

  res.redirect(302, validation.url);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
